return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[西北大漠]],["roomBgm"]=[[jiaowai]],["permission"]=1,["fullName"]=[[西北大漠(fb47_01)]],["enterable"]=1,["dsc"]=[[一望无际的大沙漠。举目望去，远方沙漠与天相接。天蓝色与沙黄色构成一幅独特而苍凉的画卷。]],["down"]=[[fb47_02]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit1"]=[[npc104z]],["canLeave"]=1,["id"]=[[fb47_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_03]],["connectPoint"]=0,["name"]=[[北门]],["permission"]=1,["fullName"]=[[北门(fb47_02)]],["enterable"]=1,["up"]=[[fb47_01]],["dsc"]=[[此处便是兰州的北门，城楼高耸，以青砖建造，楼顶亦是以青瓦铺成。远处观之，古城的肃穆之感扑面而来]],["down"]=[[fb47_06]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc104aa]],["canLeave"]=1,["id"]=[[fb47_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_04]],["connectPoint"]=0,["name"]=[[驿站]],["permission"]=1,["left"]=[[fb47_02]],["enterable"]=1,["dsc"]=[[兰州北门外的驿站，格局不大，进得站来，左侧是一排马棚，内有良驹十多匹，用于旅人更换马匹。右侧则是一个小驿馆，供行人在此歇脚。]],["fullName"]=[[驿站(fb47_03)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc104h]],["canLeave"]=1,["id"]=[[fb47_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[西北草原]],["roomBgm"]=[[jiaowai]],["permission"]=1,["left"]=[[fb47_03]],["enterable"]=1,["dsc"]=[[西北的草原，绿草茵茵，绵延至天边。行进数里，便可看到放牧的牧民和羊群。蓝天浩瀚，绿草如毯，白羊点缀其中，此番情景，极具诗意。]],["fullName"]=[[西北草原(fb47_04)]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit1"]=[[npc105b]],["canLeave"]=1,["id"]=[[fb47_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[金天观]],["permission"]=1,["fullName"]=[[金天观(fb47_05)]],["enterable"]=1,["dsc"]=[[赫赫有名的金天观。殿阁崇巍，回廊幽曲，松柏槐榆错杂遍布。观内有三十六株唐槐，称为“三十六部雷将”。]],["down"]=[[fb47_10]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc104i]],["canLeave"]=1,["id"]=[[fb47_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[林荫道]],["permission"]=1,["fullName"]=[[林荫道(fb47_06)]],["enterable"]=1,["up"]=[[fb47_02]],["dsc"]=[[一条青石铺成的道路，青石圆润，走上去十分舒服，道路两旁树木繁密，洒下一片树荫。]],["down"]=[[fb47_11]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc105c]],["canLeave"]=1,["id"]=[[fb47_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[白云观]],["permission"]=1,["fullName"]=[[白云观(fb47_07)]],["enterable"]=1,["dsc"]=[[兰州城远近闻名的白云观，殿堂雄伟，古色古香，庄严肃穆。观内有七棵参天古槐，枝叶茂盛，满含古意。]],["down"]=[[fb47_12]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc104bb]],["unit1"]=[[npc105d]],["canLeave"]=1,["id"]=[[fb47_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_09]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=1,["enterable"]=1,["dsc"]=[[太守府内的走廊，两边是红漆的栏杆，廊柱雕着精细的锦鲤花纹，上方横栏上则雕着仙鹤花纹。]],["down"]=[[fb47_14]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb47_08)]],["canLeave"]=1,["id"]=[[fb47_08]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[客房]],["permission"]=1,["left"]=[[fb47_08]],["enterable"]=1,["dsc"]=[[太守府内的待客房间。屋内摆着一张楠木雕花的垂帘床，屋正中则是一张红漆的小八仙桌，配了四个圆凳。桌上有一檀香炉，炉内正飘出缕缕轻烟。]],["fullName"]=[[客房(fb47_09)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc104f]],["unit1"]=[[npc104e]],["canLeave"]=1,["id"]=[[fb47_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_11]],["connectPoint"]=0,["name"]=[[滨河大街西]],["permission"]=1,["enterable"]=1,["up"]=[[fb47_05]],["dsc"]=[[此处是兰州城滨河大街西段，路宽六丈有余，路旁便是贯穿了整个兰州城的黄河。河水缓缓流淌，并不湍急。]],["down"]=[[fb47_18]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[滨河大街西(fb47_10)]],["canLeave"]=1,["id"]=[[fb47_10]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_12]],["connectPoint"]=0,["name"]=[[滨河大街]],["permission"]=1,["left"]=[[fb47_10]],["fullName"]=[[滨河大街(fb47_11)]],["enterable"]=1,["up"]=[[fb47_06]],["dsc"]=[[此处是兰州城滨河大街，路宽六丈有余，路旁便是贯穿了整个兰州城的黄河。河水缓缓流淌，并不湍急。]],["down"]=[[fb47_19]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc104rr]],["canLeave"]=1,["id"]=[[fb47_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_13]],["connec