ex"]=0,["unit2"]=[[npc104a]],["unit1"]=[[npc105a]],["canLeave"]=1,["id"]=[[fb47_17]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_19]],["connectPoint"]=0,["name"]=[[翠英门]],["permission"]=1,["enterable"]=1,["up"]=[[fb47_10]],["dsc"]=[[兰州城的翠英门，古墙以青砖砌成，典雅古朴，经历风吹雨打多年，墙面已经有些斑驳。]],["down"]=[[fb47_26]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[翠英门(fb47_18)]],["canLeave"]=1,["id"]=[[fb47_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_20]],["connectPoint"]=0,["name"]=[[城隍庙广场]],["permission"]=1,["left"]=[[fb47_18]],["rightDown"]=[[fb47_28]],["enterable"]=1,["up"]=[[fb47_11]],["dsc"]=[[兰州的城隍庙广场，十分宽阔，各类小贩均有在此处摆摊叫卖。临近城隍庙处，则是庙内开的贡品摊子，前来的游客可在此处购买贡品。]],["down"]=[[fb47_27]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[城隍庙广场(fb47_19)]],["canLeave"]=1,["id"]=[[fb47_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_21]],["connectPoint"]=0,["name"]=[[兰州集市]],["permission"]=1,["left"]=[[fb47_19]],["enterable"]=1,["up"]=[[fb47_12]],["dsc"]=[[兰州的大集市。兰州城内各类小贩汇聚于此，衣食住行所用之物，均可在此购买。众小贩卖力叫卖，当真是人声鼎沸，嘈杂无比。]],["down"]=[[fb47_29]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[兰州集市(fb47_20)]],["canLeave"]=1,["id"]=[[fb47_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[羊肉馆]],["permission"]=1,["left"]=[[fb47_20]],["enterable"]=1,["dsc"]=[[售卖羊肉菜肴的饭馆。在此馆中，羊肉做法多样，煎炒烹炸自不在话下，煮涮烧烤也是一应俱全。]],["fullName"]=[[羊肉馆(fb47_21)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc104t]],["unit1"]=[[npc105e]],["canLeave"]=1,["id"]=[[fb47_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb47_23]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=1,["enterable"]=1,["up"]=[[fb47_14]],["dsc"]=[[太守府内的走廊，两边是红漆的栏杆，廊柱雕着精细的锦鲤花纹，上方横栏上则雕着仙鹤花纹。]],["fullName"]=[[走廊(fb47_22)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc104mm]],["canLeave"]=1,["id"]=[[fb47_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[花园]],["permission"]=1,["left